                swap(0, i);
                siftDown(0, i);
            }
        }

        private void build() {
            for (int i = size / 2 - 1; i >= 0; i--)
                siftDown(i, size);
        }

        private void siftDown(int i, int n) {
            int largest = i;
            int l = 2 * i + 1;
            int r = 2 * i + 2;
            if (l < n && cmp.compare(get(l), get(largest)) > 0)
                largest = l;
            if (r < n && cmp.compare(get(r), get(largest)) > 0)
                largest = r;
            if (largest != i) {
                swap(i, largest);
                siftDown(largest, n);
            }
        }

        private T get(int i) {
            return arr[from + i];
        }

        private void swap(int i, int j) {
            T temp = arr[from + i];
            arr[from + i] = arr[from + j];
            arr[from + j] = temp;
        }
    }
}

